{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e3-attempts-t5/cell-FlJhVX/src/election.js","content":"/**
 * Runs the instant-runoff count over a parsed election, producing the
 * sequence of rounds and the eventual winner (or none).
 */

export function countElection({ candidates, ballots }) {
  let continuing = new Set(candidates)
  const history = [] // array of Map<name, votes>, one per round counted so far
  const rounds = []
  let winner = null

  for (;;) {
    const votes = new Map()
    for (const c of continuing) votes.set(c, 0)

    let activeTotal = 0
    for (const ballot of ballots) {
      const pick = ballot.names.find((n) => continuing.has(n))
      if (pick !== undefined) {
        votes.set(pick, votes.get(pick) + ballot.count)
        activeTotal += ballot.count
      }
    }

    const totalBallots = ballots.reduce((s, b) => s + b.count, 0)
    const exhausted = totalBallots - activeTotal

    history.push(votes)

    let roundWinner = null
    if (activeTotal > 0) {
      for (const [name, v] of votes) {
        if (v * 2 > activeTotal) {
          roundWinner = name
          break
        }
      }
    }

    if (activeTotal === 0 || roundWinner !== null) {
      rounds.push({ votes, exhausted, eliminated: null })
      winner = roundWinner
      break
    }

    const eliminated = chooseEliminated(continuing, votes, history)
    rounds.push({ votes, exhausted, eliminated })
    continuing = new Set([...continuing].filter((c) => c !== eliminated))
  }

  return { rounds, winner }
}

function chooseEliminated(continuing, votes, history) {
  let min = Infinity
  for (const c of continuing) {
    if (votes.get(c) < min) min = votes.get(c)
  }
  let survivors = [...continuing].filter((c) => votes.get(c) === min)

  while (survivors.length > 1) {
    let narrowed = false
    for (let r = 0; r < history.length; r++) {
      const roundVotes = history[r]
      const counts = survivors.map((c) => roundVotes.get(c))
      const roundMin = Math.min(...counts)
      const roundMax = Math.max(...counts)
      if (roundMin !== roundMax) {
        survivors = survivors.filter((c) => roundVotes.get(c) === roundMin)
        narrowed = true
        break
      }
    }
    if (!narrowed) break
  }

  if (survivors.length > 1) {
    survivors.sort((a, b) => (a < b ? 1 : a > b ? -1 : 0))
  }
  return survivors[0]
}
"}

